patches.new:
  const result = await saveVisualPage(page.id, page.revision, mergedChanges);
  if (!result.page) {
    setError(result.error ?? 'Enregistrement impossible.');
    return;
  }
  const savedPage = result.page as View;
  pageRef.current = savedPage;
  setPage(savedPage);
  setChanges(savedPage.changes);
  setDrafts({});
  setAltDrafts({});
  setNotice('Brouillon enregistré sur le VPS. La page publiée reste inchangée.');

  if (showHistory) {
    try {
      const histRes = await getVisualPageHistory(savedPage.id);
      if (
        pageRef.current.id === savedPage.id &&
        pageRef.current.revision === savedPage.revision &&
        !histRes.error &&
        histRes.history
      ) {
        setHistoryList(histRes.history);
      }
    } catch {
      // Relecture de l’historique non bloquante après enregistrement réussi
    }
  }
} catch {
  setError('Connexion interrompue. Vos modifications restent ici. Réessayez.');
}

